def create_existing_user_profiles(apps, schema_editor):
    profile_model = apps.get_model("dashboard", "UserAccessProfile")
    user_model = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    database = schema_editor.connection.alias
    profiles = [
        profile_model(
            user_id=user_id,
            role="admin" if is_superuser else "analyst",
        )
        for user_id, is_superuser in user_model.objects.using(database).values_list(
            "pk", "is_superuser"
        )
    ]
    profile_model.objects.using(database).bulk_create(profiles, ignore_conflicts=True)


